"""Fresh five-source Lake build and unchanged official checker replay."""
from pathlib import Path
import argparse,hashlib,json,os,shutil,subprocess,time
arg=argparse.ArgumentParser();arg.add_argument('--lean',type=Path,required=True);arg.add_argument('--out',type=Path,required=True);a=arg.parse_args()
root=Path(__file__).resolve().parent;out=a.out.resolve();out.mkdir(exist_ok=False)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert sha(a.lean)=='ec7a472d1c12a09b0c0c718f7427c2be527b3f5f07810fdbe076c2507c7a91ea'
assert sha(root/'Check.lean')=='b882f2527a1d6e720828a0c729cc80c3977905ed9207d09af22f8d153a073905'
meta=json.loads((root/'INPUTS.json').read_text())
for f in meta['files']:assert sha(root/f['path'])==f['sha256']
project=out/'project';project.mkdir();shutil.copytree(root/'sources',project/'lean')
shutil.copyfile(root/'Check.lean',project/'Check.lean')
(project/'lean/lakefile.toml').write_text('name = "clockdrop"\nversion = "0.1.0"\n[[lean_lib]]\nname = "Ruliology"\n')
env=dict(os.environ,PATH=str(a.lean.parent)+os.pathsep+os.environ.get('PATH',''),LEAN_NUM_THREADS='1');env.pop('LEAN_PATH',None);env.pop('LEAN_SRC_PATH',None)
def run(args,name):
    with (out/name).open('wb') as log:r=subprocess.run(args,cwd=project/'lean',env=env,stdout=log,stderr=subprocess.STDOUT)
    if r.returncode:print((out/name).read_text(encoding='utf-8',errors='replace')[-7000:]);r.check_returncode()
start=time.monotonic();module='Ruliology.CellularAutomata.Rule30PeriodicThreeFive';lake=a.lean.parent/'lake.exe'

for idx,dependency in enumerate(meta['build_order']):run([str(lake),'build',dependency],f'build-{idx:02d}.log')
(out/'build.log').write_bytes(b''.join((out/f'build-{i:02d}.log').read_bytes() for i in range(len(meta['build_order']))))
specs={'Ruliology.CellularAutomata.Rule30InverseRuns': ['Ruliology.CellularAutomata.Rule30InverseRuns.finite_inverse_iff_scan', 'Ruliology.CellularAutomata.Rule30InverseRuns.scan_blocks', 'Ruliology.CellularAutomata.Rule30InverseRuns.finite_inverse_run_blocks'], 'Ruliology.CellularAutomata.Rule30GateInverseMerge': ['Ruliology.CellularAutomata.Rule30GateInverseMerge.heads_agree_after_eleven', 'Ruliology.CellularAutomata.Rule30GateInverseMerge.finite_preimage_iff_head_true', 'Ruliology.CellularAutomata.Rule30GateInverseMerge.second_inverse_heads_agree', 'Ruliology.CellularAutomata.Rule30GateInverseMerge.second_inverse_finite_head_independent', 'Ruliology.CellularAutomata.Rule30GateInverseMerge.first_inverse_heads_agree', 'Ruliology.CellularAutomata.Rule30GateInverseMerge.first_preimage_exists_iff_prescribed', 'Ruliology.CellularAutomata.Rule30GateInverseMerge.all_two_step_heads_agree', 'Ruliology.CellularAutomata.Rule30GateInverseMerge.two_step_finiteness_independent', 'Ruliology.CellularAutomata.Rule30GateInverseMerge.any_two_step_preimage_iff_canonical', 'Ruliology.CellularAutomata.Rule30GateInverseMerge.gate_prefix_coverage', 'Ruliology.CellularAutomata.Rule30GateInverseMerge.first_actual_preimage_iff_prescribed', 'Ruliology.CellularAutomata.Rule30GateInverseMerge.any_actual_two_step_preimage_iff_canonical', 'Ruliology.CellularAutomata.Rule30GateInverseMerge.wall_and_head_agree', 'Ruliology.CellularAutomata.Rule30GateInverseMerge.finite_actual_image_transfer', 'Ruliology.CellularAutomata.Rule30GateInverseMerge.single_seed_left_inverse_finite'], 'Ruliology.CellularAutomata.Rule30GatePastThree': ['Ruliology.CellularAutomata.Rule30GatePastThree.three_legal_pasts_agree', 'Ruliology.CellularAutomata.Rule30GatePastThree.legal_gate_prefix_edits_agree', 'Ruliology.CellularAutomata.Rule30GatePastThree.legal_gate_prefix_edits_finite_iff', 'Ruliology.CellularAutomata.Rule30GatePastThree.history_gate_prefix', 'Ruliology.CellularAutomata.Rule30GatePastThree.reconstructed_gate_prefix_edits_agree', 'Ruliology.CellularAutomata.Rule30GatePastThree.reconstructed_gate_prefix_edits_finite_iff'], 'Ruliology.CellularAutomata.Rule30PeriodicGateTail': ['Ruliology.CellularAutomata.Rule30PeriodicGateTail.profile_step', 'Ruliology.CellularAutomata.Rule30PeriodicGateTail.scan_sync', 'Ruliology.CellularAutomata.Rule30PeriodicGateTail.reference_rec', 'Ruliology.CellularAutomata.Rule30PeriodicGateTail.back_tail', 'Ruliology.CellularAutomata.Rule30PeriodicGateTail.history_tail', 'Ruliology.CellularAutomata.Rule30PeriodicGateTail.all_histories_agree', 'Ruliology.CellularAutomata.Rule30PeriodicGateTail.lam_gap_five_tail', 'Ruliology.CellularAutomata.Rule30PeriodicGateTail.gap_five_histories_agree', 'Ruliology.CellularAutomata.Rule30PeriodicGateTail.gate_history_tail', 'Ruliology.CellularAutomata.Rule30PeriodicGateTail.boundary_odd_trace', 'Ruliology.CellularAutomata.Rule30PeriodicGateTail.arbitrary_gate_pasts_agree', 'Ruliology.CellularAutomata.Rule30PeriodicGateTail.back_tail_bound', 'Ruliology.CellularAutomata.Rule30PeriodicGateTail.history_tail_bound', 'Ruliology.CellularAutomata.Rule30PeriodicGateTail.gate_history_tail_bound', 'Ruliology.CellularAutomata.Rule30PeriodicGateTail.arbitrary_gate_pasts_agree_from'], 'Ruliology.CellularAutomata.Rule30SynchronizingCarrier': ['Ruliology.CellularAutomata.Rule30SynchronizingCarrier.row_add_multiple', 'Ruliology.CellularAutomata.Rule30SynchronizingCarrier.back_tail_bound', 'Ruliology.CellularAutomata.Rule30SynchronizingCarrier.history_tail_bound', 'Ruliology.CellularAutomata.Rule30SynchronizingCarrier.gate_history_tail_bound', 'Ruliology.CellularAutomata.Rule30SynchronizingCarrier.gate_pasts_agree_from', 'Ruliology.CellularAutomata.Rule30SynchronizingCarrier.reconstructed_gate_pasts_agree_from', 'Ruliology.CellularAutomata.Rule30SynchronizingCarrier.gap_five_bound_recovered'], 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive': ['Ruliology.CellularAutomata.Rule30PeriodicThreeFive.row_step', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.row_reference', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.row_sync', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.full_initial', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.full_step', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.recon_full', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.lam_tail', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.gate_legal_eight_windows', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.boundary_odd_trace', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.arbitrary_gate_pasts_agree_from', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.arbitrary_gate_pasts_agree', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.recon_shift', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.temporal_phase_tail', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.boundary_shift_odd_trace', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.shifted_gate_pasts_agree_from', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.prefixed_gate_tail', 'Ruliology.CellularAutomata.Rule30PeriodicThreeFive.eventually_three_five_pasts_agree_from']}
checks={};allheads=[]
for index,(name,short) in enumerate(specs.items()):
    heads=short;allheads+=heads
    cmd=[str(lake),'env',str(a.lean),'--run',str(project/'Check.lean'),name,'--claim','partial']
    for h in heads:cmd+=['--headline',h]
    log=f'check-{index}.log';run(cmd,log)
    c=json.loads(next(s for s in reversed((out/log).read_text(encoding='utf-8').splitlines()) if s.startswith('{')))
    assert c['verdict']=='pass' and c['replay']['ok'] and not c['newAxioms'] and all(h['ok'] and h['typeMatches'] for h in c['headlines'])
    checks[name]=c
types=out/'Types.lean';types.write_text('import Ruliology.CellularAutomata.Rule30InverseRuns\nimport Ruliology.CellularAutomata.Rule30GateInverseMerge\nimport Ruliology.CellularAutomata.Rule30GatePastThree\nimport Ruliology.CellularAutomata.Rule30PeriodicGateTail\nimport Ruliology.CellularAutomata.Rule30SynchronizingCarrier\nimport Ruliology.CellularAutomata.Rule30PeriodicThreeFive\n'+''.join('#check @'+h+'\n#print axioms '+h+'\n' for h in allheads),encoding='utf-8')
run([str(lake),'env',str(a.lean),str(types)],'Types.log')
for f in meta['files']:assert sha(root/f['path'])==f['sha256']
assert b'warning:' not in (out/'build.log').read_bytes()
assert sum(c['replay']['constants'] for c in checks.values())==583 and len(allheads)==63
r={'passed':True,'official_pin':meta['pin'],'fresh_source_modules':14,'reused_objects':False,'whole_catalog_build':False,'checkers':checks,'owned_declarations':sum(c['replay']['constants'] for c in checks.values()),'headlines':len(allheads),'source_files':meta['files'],'source_warnings':b'warning:' in (out/'build.log').read_bytes(),'seconds':time.monotonic()-start}
(out/'RESULT.json').write_text(json.dumps(r,indent=2)+'\n')
print(json.dumps({'passed':True,'constants':r['owned_declarations'],'headlines':r['headlines'],'source_warnings':r['source_warnings'],'seconds':r['seconds']}))
